public class ModBlocks{public static final DeferredRegister<Block> BLOCKS=DeferredRegister.create(ForgeRegistries.BLOCKS,AstralitaMod.MODID);public static final RegistryObject<Block> MINERIO_ASTRALITA=BLOCKS.register("minerio_astralita",()->new Block(BlockBehaviour.Properties.of().mapColor(MapColor.COLOR_LIGHT_BLUE).strength(7,12).requiresCorrectToolForDrops().lightLevel(s->4)));public static final RegistryObject<Block> BLOCO_ASTRALITA=BLOCKS.register("bloco_astralita",()->new Block(BlockBehaviour.Properties.of().mapColor(MapColor.QUARTZ).strength(8,15).requiresCorrectToolForDrops().lightLevel(s->6)));public static void register(IEventBus b){BLOCKS.register(b);}}
